-- Importar uma vez em um banco vazio. Conteúdo público preservado; sem contas antigas.
CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, login VARCHAR(100) NOT NULL UNIQUE, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, can_manage_users BOOLEAN NOT NULL DEFAULT 1, password_change_required BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(200) NOT NULL, price DECIMAL(10,2) NOT NULL, short_description TEXT NOT NULL, details TEXT NOT NULL, image_path VARCHAR(255) NOT NULL, image_alt VARCHAR(200) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE site_contacts (id INT PRIMARY KEY, phone_label VARCHAR(255) NOT NULL, phone_link VARCHAR(2048) NOT NULL, email_label VARCHAR(254) NOT NULL, email_link VARCHAR(2048) NOT NULL, instagram_label VARCHAR(255) NOT NULL, instagram_link VARCHAR(2048) NOT NULL, address TEXT NOT NULL, maps_link VARCHAR(2048) NOT NULL, maps_embed VARCHAR(2048) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE about_content (id INT PRIMARY KEY, intro_title VARCHAR(200) NOT NULL, intro_text TEXT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE about_blocks (id INT PRIMARY KEY, position INT NOT NULL UNIQUE, badge VARCHAR(100) NOT NULL, title VARCHAR(200) NOT NULL, text TEXT NOT NULL, image_path VARCHAR(255) NOT NULL, image_alt VARCHAR(200) NOT NULL, inversed BOOLEAN NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE login_attempts (identity_hash CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, window_start BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
